"unbekannt":["unbekannt", "unknown"],
"offline_ansicht_der_mac_ist":["Offline-Ansicht – der Mac ist nicht erreichbar. Stand {0}; nur lesen. {1}", "Offline view – the Mac is not reachable. As of {0}; read only. {1}"],
